package com.example.csvstatsplayerbatch.batch;
import org.springframework.batch.item.Chunk; import org.springframework.batch.item.ItemWriter; import org.springframework.jdbc.core.JdbcTemplate;
public class ResultsWriter implements ItemWriter<ResultRow>{
 static final String SQL="INSERT INTO stats_player (id,match_id,name,team,pts,reb,ast,min,fgm,fga,twopm,twopa,threepm,threepa,ftm,fta,plus_minus,offensive_rebounds,dr,pf,st,turnovers,bs,ba,tfs,source_event_id) VALUES (nextval('stats_player_seq'),?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(match_id,name,team) DO UPDATE SET pts=EXCLUDED.pts,reb=EXCLUDED.reb,ast=EXCLUDED.ast,min=EXCLUDED.min,fgm=EXCLUDED.fgm,fga=EXCLUDED.fga,twopm=EXCLUDED.twopm,twopa=EXCLUDED.twopa,threepm=EXCLUDED.threepm,threepa=EXCLUDED.threepa,ftm=EXCLUDED.ftm,fta=EXCLUDED.fta,plus_minus=EXCLUDED.plus_minus,offensive_rebounds=EXCLUDED.offensive_rebounds,dr=EXCLUDED.dr,pf=EXCLUDED.pf,st=EXCLUDED.st,turnovers=EXCLUDED.turnovers,bs=EXCLUDED.bs,ba=EXCLUDED.ba,tfs=EXCLUDED.tfs,source_event_id=EXCLUDED.source_event_id,updated_at=CURRENT_TIMESTAMP";
 private final JdbcTemplate jdbc;private final String source;public ResultsWriter(JdbcTemplate j,String s){jdbc=j;source=s;} public void write(Chunk<? extends ResultRow> c){jdbc.batchUpdate(SQL,c.getItems(),c.size(),(s,r)->{for(int i=0;i<24;i++){String value=r.values()[i]; if(isNumericColumn(i)&&value!=null)s.setObject(i+1,Integer.valueOf(value)); else s.setObject(i+1,value);}s.setObject(25,"csv-"+source+"-"+r.recordNumber());});}
 private static boolean isNumericColumn(int i){return i>=3&&i!=6;}
}
